package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

type stack []int

var (
	errEmptyStack = errors.New("empty stack")
	errOneValue   = errors.New("only one value on the stack")
	errDivideByZero = errors.New("divide by zero")
	errIllegal    = errors.New("illegal operation")
	errUndefined  = errors.New("undefined operation")
)

type word func(*stack) error

func (s *stack) pop() (int, error) {
	if len(*s) == 0 {
		return 0, errEmptyStack
	}
	v := (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-1]
	return v, nil
}

func (s *stack) push(v int) { *s = append(*s, v) }

func (s *stack) pop2() (int, int, error) {
	if len(*s) < 2 {
		return 0, 0, errOneValue
	}
	b := (*s)[len(*s)-2]
	a := (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-2]
	return a, b, nil
}

func Forth(input []string) ([]int, error) {
	st := &stack{}
	dict := map[string]word{
		"+": func(s *stack) error {
			a, b, err := s.pop2()
			if err != nil { return err }
			s.push(a + b)
			return nil
		},
		...
	}
	// handle definitions spanning lines
	var defining string
	var body []token
	...
}
```

