```go
func compile(tokens []string, dict map[string]word) ([]action, error) {
	var acts []action
	for _, tok := range tokens {
		if n, err := strconv.Atoi(tok); err == nil {
			n := n
			acts = append(acts, func(s *stack) error { s.push(n); return nil })
		} else if w, ok := dict[tok]; ok {
			acts = append(acts, w)
		} else {
			return nil, fmt.Errorf("undefined operation %q", tok)
		}
	}
	return acts, nil
}
```

